def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys
    import os

    if sys.platform != 'win32':
        return cmd

    if not cmd:
        return cmd

    script_path = cmd[0]
    if not os.path.isfile(script_path):
        return cmd

    try:
        with open(script_path, 'r', encoding='utf-8') as file:
            first_line = file.readline().strip()
    except Exception:
        return cmd

    if not first_line.startswith('#!'):
        return cmd

    shebang_parts = first_line[2:].strip().split()
    if not shebang_parts:
        return cmd

    python_exe = shebang_parts[0]
    if not python_exe.lower().endswith(('python', 'python.exe')):
        return cmd

    # Construct the new command with the shebang's python executable
    new_cmd = [python_exe] + shebang_parts[1:] + list(cmd[1:])
    return tuple(new_cmd)

