def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a dictionary to track classes and their bases
        class_bases = {cls: set(cls.__bases__) for cls in classes}

        # Identify all unique classes (including bases)
        all_classes = set(classes)
        for bases in class_bases.values():
            all_classes.update(bases)

        # Initialize a dictionary to track minimal bases
        minimal_bases = {cls: set() for cls in all_classes}

        # Function to determine minimal bases
        def get_minimal_bases(cls):
            if not minimal_bases[cls]:
                minimal_bases[cls] = set(class_bases[cls])
                to_remove = set()
                for base in minimal_bases[cls]:
                    to_remove.update(get_minimal_bases(base))
                minimal_bases[cls] -= to_remove
            return minimal_bases[cls]

        # Compute minimal bases for all classes
        for cls in all_classes:
            get_minimal_bases(cls)

        # Filter original classes to their minimal bases
        result = []
        for cls in classes:
            if any(issubclass(base, cls) and base is not cls for base in classes):
                continue
            result.append(cls)

        # Sort the result to maintain order
        result.sort(key=lambda x: classes.index(x))

        return result

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

