def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str) or not os.path.isdir(folder):
        raise ValueError("Provided folder path is invalid or not a directory")

    packages_data = {}

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    base_name = os.path.splitext(file)[0]
                    if base_name not in packages_data:
                        packages_data[base_name] = []
                    packages_data[base_name].append(ET.tostring(root_element, encoding='unicode'))
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}")
                except Exception as e:
                    print(f"Warning: An error occurred while processing file {file_path}: {e}")

    return packages_data

