def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    units = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks"
    }

    frequency = frequency.strip().lower()
    for unit in units:
        if frequency.endswith(unit):
            try:
                number = int(frequency[:-len(unit)].strip())
                return datetime.timedelta(**{units[unit]: number})
            except ValueError:
                raise ValueError(f"Invalid frequency value: {frequency}")

    # Check for plural forms
    for unit in units:
        plural_unit = unit + "s"
        if frequency.endswith(plural_unit):
            try:
                number = int(frequency[:-len(plural_unit)].strip())
                return datetime.timedelta(**{units[unit]: number})
            except ValueError:
                raise ValueError(f"Invalid frequency value: {frequency}")

    raise ValueError(f"Cannot parse frequency: {frequency}")

