def resolve_environment_variables(config):
    import os
    import re

    def replace_with_env(match):
        var_name = match.group(1)
        return os.getenv(var_name, f"${var_name}")

    config_str = json.dumps(config)
    config_str = re.sub(r'\$\{(\w+)\}', replace_with_env, config_str)
    return json.loads(config_str)

