def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree
    from xml.etree.ElementTree import ParseError

    try:
        # Attempt to parse the document as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        try:
            # If JSON parsing fails, attempt to parse as XRD XML
            root = ElementTree.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid root element for XRD")

            xrd_data = {
                'subject': root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject').text,
                'aliases': [alias.text for alias in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias')],
                'links': []
            }

            for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                link_data = {
                    'rel': link.get('rel'),
                    'href': link.get('href'),
                    'template': link.get('template')
                }
                xrd_data['links'].append(link_data)

            return xrd_data
        except (ParseError, ValueError):
            # If both parsing methods fail, return an empty dictionary
            return {}

