def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg_name, arg_value in values_dict.items():
        try:
            action = next(action for action in parser._actions if action.dest == arg_name)
        except StopIteration:
            continue  # Skip if the argument is not found in the parser

        if action.type:
            try:
                values_dict[arg_name] = action.type(arg_value)
            except (ValueError, TypeError):
                raise ValueError(f"Could not convert argument '{arg_name}' to type {action.type.__name__}")
        elif action.nargs == 0 and isinstance(action, argparse._StoreTrueAction):
            values_dict[arg_name] = action.const if arg_value.lower() in ['true', '1', 'yes', 'y'] else argparse.SUPPRESS
        elif action.nargs == 0 and isinstance(action, argparse._StoreFalseAction):
            values_dict[arg_name] = action.const if arg_value.lower() in ['false', '0', 'no', 'n'] else argparse.SUPPRESS
        elif action.choices:
            if arg_value not in action.choices:
                raise ValueError(f"Invalid choice for argument '{arg_name}': {arg_value}. Valid choices are {action.choices}")
        # Handle other types of actions as needed

    return values_dict

